golden.canonicalQuery:
run: duckdb.table('data/order_items.parquet') -> {
  group_by:
    order_year is year(created_at)
    order_month is month(created_at)
  aggregate: monthly_sales is sale_price.sum()
  order_by: order_year asc, monthly_sales desc
  calculate: rank_in_year is rank() { partition_by: order_year }
} -> {
  where: rank_in_year = 1
  select: order_year, order_month, monthly_sales
  order_by: order_year asc
}

run: duckdb.table('data/order_items.parquet') -> {
  where: delivered_at is not null
  group_by: order_year is year(created_at)
  aggregate: avg_days_to_deliver is round(avg(days(created_at::date to delivered_at)), 3)
  order_by: order_year
  calculate: prior_year_days is lag(avg_days_to_deliver)
} -> {
  where: order_year = 2022
  select:
    avg_days_2022 is avg_days_to_deliver
    avg_days_2021 is prior_year_days
    yoy_change_days is round(avg_days_to_deliver - prior_year_days, 3)
}

run: duckdb.table('data/order_items.parquet') -> {
  where: status = 'Returned'
  aggregate:
    returned_items is count()
    returned_at_equals_created_at is count() { where: returned_at = created_at }
    naive_days_delivered_to_returned is round(avg(days(delivered_at to returned_at::date)), 4)
}

run: duckdb.table('data/order_items.parquet') -> {
  group_by: order_id
  aggregate:
    lines is count()
    returned_lines is count() { where: status = 'Returned' }
} -> {
  aggregate:
    returned_orders is count() { where: returned_lines > 0 }
    fully_returned_orders is count() { where: returned_lines = lines }
    partially_returned_orders is count() { where: returned_lines > 0 and returned_lines < lines }
}

run: duckdb.table('data/order_items.parquet') -> {
  aggregate:
    open_orders is count(order_id) { where: status = 'Processing' or status = 'Shipped' }
    open_line_items is count() { where: status = 'Processing' or status = 'Shipped' }
    undelivered_including_cancelled is count(order_id) { where: delivered_at is null }
}

run: duckdb.table('data/order_items.parquet') -> {
  where: year(created_at) = 2022
  aggregate:
    units_sold is count() { where: status != 'Cancelled' }
    all_2022_lines is count()
    cancelled_2022_lines is count() { where: status = 'Cancelled' }
}
